def _parse_event(raw):
    if not isinstance(raw, dict): raise InvalidConsentEvent("each event must be an object")
    for field in _EVENT_FIELDS:
        if field not in raw: raise InvalidConsentEvent(f"event is missing {field}")
    event_id = _require_string(raw, "event_id", InvalidConsentEvent)
    consent_id = _require_string(raw, "consent_id", InvalidConsentEvent)
    version = raw["version"]
    if not isinstance(version, int) or isinstance(version, bool) or version < 1:
        raise InvalidConsentEvent("version must be a positive integer")
    occurred_at = _parse_time(raw["occurred_at"], InvalidConsentEvent)
    etype = raw["type"]
    if etype not in _EVENT_TYPE_SET: raise InvalidConsentEvent("type must be 'grant', 'amend' or 'revoke'")
